package local.expenses;

import android.app.*;
import android.os.*;
import android.content.*;
import android.graphics.Color;
import android.graphics.Typeface;
import android.graphics.drawable.GradientDrawable;
import android.view.*;
import android.view.inputmethod.InputMethodManager;
import android.widget.*;
import java.math.*;
import java.text.*;
import java.util.*;
import java.io.*;

public class MainActivity extends Activity {
 private final int INK=0xff17181c,BLUE=0xff007aff,MUTED=0xff83838d,BG=0xfff2f2f7,LINE=0xffe8e8ed,RED=0xffff3b30;
 private LinearLayout root,page,categoryBox;private EditText amount,note;private TextView dateView;
 private LedgerDatabase db;private java.util.List<Expense> entries=new ArrayList<>();private java.util.List<Category> categories=new ArrayList<>();
 private String selected="",screen="home",filter="Все";private long editId=0,editTime=0;private boolean busy=false,payment=false;private String initialAmount;
 private int loadGeneration=0;private Button saveButton;
 private interface Job {void run() throws Exception;}
 int dp(int x){return Math.round(x*getResources().getDisplayMetrics().density);}
 public void onCreate(Bundle state){super.onCreate(state);db=LedgerDatabase.get(this);readIntent();loading();load(()->{if(state!=null)restore(state);else if(payment)form(null);else home();});}
 protected void onSaveInstanceState(Bundle state){super.onSaveInstanceState(state);state.putString("screen",screen);state.putString("selected",selected);state.putString("filter",filter);state.putBoolean("payment",payment);if(screen.equals("form")){state.putLong("editId",editId);state.putLong("editTime",editTime);state.putString("amount",amount.getText().toString());state.putString("note",note.getText().toString());}}
 private void restore(Bundle state){selected=state.getString("selected",selected);filter=state.getString("filter","Все");payment=state.getBoolean("payment",false);String tab=state.getString("screen","home");if(tab.equals("form")){Expense e=null;long id=state.getLong("editId");for(Expense item:entries)if(item.id==id)e=item;form(e);selected=state.getString("selected",selected);renderCategories();editTime=state.getLong("editTime",System.currentTimeMillis());amount.setText(state.getString("amount",""));note.setText(state.getString("note",""));updateDate();}else if(tab.equals("settings"))settings();else home();}
 protected void onNewIntent(Intent i){super.onNewIntent(i);setIntent(i);readIntent();load(()->{if(payment)form(null);else home();});}
 private void readIntent(){payment=getIntent().getBooleanExtra("payment",false);initialAmount=getIntent().getStringExtra("detectedAmount");}
 private void loading(){base("home");page.addView(label("Hisob",34,INK,true));page.addView(label("Подготавливаем твою историю…",16,MUTED,false));}
 private void error(Exception e){if(isFinishing()||isDestroyed())return;new AlertDialog.Builder(this).setTitle("Не удалось выполнить действие").setMessage("Данные не изменены. Попробуй ещё раз. Если ошибка повторится, сообщи мне: "+e.getClass().getSimpleName()).setPositiveButton("Понятно",null).show();}
 private void load(Runnable done){int generation=++loadGeneration;LedgerDatabase.IO.execute(()->{try{db.importLegacy(this);java.util.List<Expense> es=db.ledger().expenses();java.util.List<Category> cs=db.ledger().categories();String last=db.ledger().setting("lastCategory");runOnUiThread(()->{if(isDestroyed()||generation!=loadGeneration)return;entries=es;categories=cs;if(selected.isEmpty()&&last!=null)selected=last;done.run();});}catch(Exception e){runOnUiThread(()->{error(e);page.addView(action("Повторить",()->load(()->home()),true));});}});}
 private void change(Job job,Runnable done){if(busy)return;busy=true;if(saveButton!=null)saveButton.setEnabled(false);LedgerDatabase.IO.execute(()->{try{job.run();runOnUiThread(()->{busy=false;if(saveButton!=null)saveButton.setEnabled(true);load(done);});}catch(Exception e){runOnUiThread(()->{busy=false;if(saveButton!=null)saveButton.setEnabled(true);error(e);});}});}
 private GradientDrawable shape(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));return d;}
 private TextView label(String text,int size,int color,boolean bold){TextView t=new TextView(this);t.setText(text);t.setTextSize(size);t.setTextColor(color);t.setTypeface(Typeface.create(bold?"sans-serif-medium":"sans-serif",bold?Typeface.BOLD:Typeface.NORMAL));t.setPadding(0,dp(5),0,dp(5));return t;}
 private LinearLayout column(){LinearLayout l=new LinearLayout(this);l.setOrientation(1);return l;}
 private void gap(LinearLayout l,int h){Space s=new Space(this);l.addView(s,new LinearLayout.LayoutParams(1,dp(h)));}
 private LinearLayout card(){LinearLayout l=column();l.setPadding(dp(18),dp(15),dp(18),dp(15));l.setBackground(shape(Color.WHITE,22));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,dp(7),0,dp(7));page.addView(l,p);return l;}
 private Button action(String title,Runnable run,boolean primary){Button b=new Button(this);b.setText(title);b.setAllCaps(false);b.setTextSize(16);b.setTypeface(Typeface.create("sans-serif-medium",Typeface.NORMAL));b.setTextColor(primary?Color.WHITE:BLUE);b.setBackground(shape(primary?BLUE:Color.WHITE,17));b.setStateListAnimator(null);b.setMinHeight(dp(52));b.setPadding(dp(14),dp(10),dp(14),dp(10));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,dp(6),0,dp(6));b.setLayoutParams(p);b.setOnClickListener(v->{if(!busy)run.run();});return b;}
 private void base(String tab){screen=tab;saveButton=null;root=column();root.setBackgroundColor(BG);root.setFitsSystemWindows(true);getWindow().setStatusBarColor(BG);getWindow().setNavigationBarColor(BG);getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR);setContentView(root);ScrollView scroll=new ScrollView(this);scroll.setClipToPadding(false);page=column();page.setPadding(dp(22),dp(14),dp(22),dp(24));page.setFocusableInTouchMode(true);page.requestFocus();scroll.addView(page);scroll.post(()->scroll.scrollTo(0,0));root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));LinearLayout nav=new LinearLayout(this);nav.setPadding(dp(10),dp(8),dp(10),dp(8));nav.setBackgroundColor(Color.WHITE);String[] names={"Обзор","＋ Расход","Настройки"};String[] keys={"home","form","settings"};for(int i=0;i<3;i++){final int index=i;TextView t=label(names[i],14,keys[i].equals(tab)?BLUE:MUTED,keys[i].equals(tab));t.setGravity(Gravity.CENTER);t.setMinHeight(dp(45));nav.addView(t,new LinearLayout.LayoutParams(0,-2,1));t.setOnClickListener(v->{if(busy)return;if(index==0)home();else if(index==1){payment=false;initialAmount=null;form(null);}else settings();});}root.addView(nav);}
 private String money(long cents){DecimalFormat f=new DecimalFormat("#,##0.00",DecimalFormatSymbols.getInstance(new Locale("ru")));return f.format(BigDecimal.valueOf(cents,2));}
 private void section(String s){gap(page,14);page.addView(label(s.toUpperCase(new Locale("ru")),12,MUTED,true));}
 private void home(){base("home");page.addView(label("Hisob",33,INK,true));page.addView(label("Всё под твоим контролем",15,MUTED,false));Calendar start=Calendar.getInstance();start.set(Calendar.DAY_OF_MONTH,1);start.set(Calendar.HOUR_OF_DAY,0);start.set(Calendar.MINUTE,0);start.set(Calendar.SECOND,0);start.set(Calendar.MILLISECOND,0);long from=start.getTimeInMillis();start.add(Calendar.MONTH,1);long until=start.getTimeInMillis();long total=0;int count=0;Map<String,Long> totals=new LinkedHashMap<>();for(Expense e:entries)if(e.time>=from&&e.time<until){total+=e.cents;count++;totals.put(e.category,totals.getOrDefault(e.category,0L)+e.cents);}LinearLayout hero=card();hero.setBackground(shape(0xffe6efff,24));hero.addView(label(new SimpleDateFormat("LLLL yyyy",new Locale("ru")).format(new Date()),15,BLUE,true));hero.addView(label(money(total)+" с.",36,INK,true));hero.addView(label("Расходов за месяц: "+count,14,MUTED,false));hero.addView(action("＋ Добавить расход",()->{payment=false;initialAmount=null;form(null);},true));if(!totals.isEmpty()){section("По категориям · этот месяц");LinearLayout c=card();for(Map.Entry<String,Long> e:totals.entrySet()){LinearLayout row=new LinearLayout(this);TextView name=label(e.getKey(),16,INK,false);row.addView(name,new LinearLayout.LayoutParams(0,-2,1));row.addView(label(money(e.getValue())+" с.",16,INK,true));c.addView(row);}}
 section("История · все записи");HorizontalScrollView hs=new HorizontalScrollView(this);hs.setHorizontalScrollBarEnabled(false);LinearLayout filters=new LinearLayout(this);java.util.List<String> names=new ArrayList<>();names.add("Все");for(Category c:categories)names.add(c.name);for(String n:names){TextView chip=label(n,14,n.equals(filter)?Color.WHITE:INK,false);chip.setPadding(dp(14),dp(10),dp(14),dp(10));chip.setBackground(shape(n.equals(filter)?BLUE:Color.WHITE,20));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-2,-2);p.setMargins(0,0,dp(7),0);filters.addView(chip,p);chip.setOnClickListener(v->{filter=n;home();});}hs.addView(filters);page.addView(hs);gap(page,8);int visible=0;for(Expense e:entries){if(!filter.equals("Все")&&!e.category.equals(filter))continue;visible++;LinearLayout row=card();LinearLayout top=new LinearLayout(this);TextView cat=label(e.category,17,INK,true);top.addView(cat,new LinearLayout.LayoutParams(0,-2,1));top.addView(label(money(e.cents)+" с.",17,INK,true));row.addView(top);row.addView(label(new SimpleDateFormat("dd MMM yyyy · HH:mm",new Locale("ru")).format(new Date(e.time))+"   ›",13,MUTED,false));if(!e.note.isEmpty())row.addView(label(e.note,14,MUTED,false));row.setOnClickListener(v->{payment=false;form(e);});row.setContentDescription("Изменить расход: "+e.category+", "+money(e.cents));}if(visible==0){LinearLayout empty=card();empty.addView(label("Пока нет расходов",21,INK,true));empty.addView(label("Добавь первый — он появится здесь.",15,MUTED,false));}}
 private EditText input(String hint,int size){EditText e=new EditText(this);e.setHint(hint);e.setTextSize(size);e.setTextColor(INK);e.setHintTextColor(0xffb1b1bb);e.setBackgroundColor(Color.TRANSPARENT);e.setPadding(0,dp(8),0,dp(8));return e;}
 private void form(Expense edit){editId=edit==null?0:edit.id;editTime=edit==null?System.currentTimeMillis():edit.time;if(edit!=null)selected=edit.category;base("form");page.addView(label(edit==null?"Новый расход":"Изменить расход",30,INK,true));page.addView(label(payment?"Сумма из Alif · проверь и сохрани":"Сумма, категория и немного контекста",14,MUTED,false));LinearLayout sum=card();sum.addView(label("СУММА В СОМОНИ",12,MUTED,true));amount=input("0,00",44);amount.setSingleLine(true);amount.setInputType(8194);amount.setId(1001);if(edit!=null)amount.setText(BigDecimal.valueOf(edit.cents,2).toPlainString());else if(payment&&initialAmount!=null)amount.setText(initialAmount);sum.addView(amount);section("Категория");categoryBox=column();page.addView(categoryBox);renderCategories();page.addView(action("＋ Новая категория",()->newCategory(),false));section("Детали");LinearLayout details=card();dateView=label("",16,BLUE,false);updateDate();details.addView(dateView);dateView.setMinHeight(dp(44));dateView.setOnClickListener(v->pickDate());View line=new View(this);line.setBackgroundColor(LINE);details.addView(line,new LinearLayout.LayoutParams(-1,dp(1)));note=input("Заметка · необязательно",16);note.setId(1002);note.setMaxLines(4);note.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(1000)});if(edit!=null)note.setText(edit.note);details.addView(note);gap(page,12);saveButton=action(edit==null?"Сохранить расход":"Сохранить изменения",()->save(),true);page.addView(saveButton);if(edit!=null){Button delete=action("Удалить расход",()->confirmDelete(edit),false);delete.setTextColor(RED);page.addView(delete);}if(payment)page.addView(action("Пропустить",()->finish(),false));}
 private void updateDate(){dateView.setText("Дата   "+new SimpleDateFormat("dd MMM yyyy · HH:mm",new Locale("ru")).format(new Date(editTime))+"   ›");}
 private void pickDate(){Calendar c=Calendar.getInstance();c.setTimeInMillis(editTime);new DatePickerDialog(this,(v,y,m,d)->{c.set(y,m,d);new TimePickerDialog(this,(t,h,min)->{c.set(Calendar.HOUR_OF_DAY,h);c.set(Calendar.MINUTE,min);editTime=c.getTimeInMillis();updateDate();},c.get(Calendar.HOUR_OF_DAY),c.get(Calendar.MINUTE),true).show();},c.get(Calendar.YEAR),c.get(Calendar.MONTH),c.get(Calendar.DAY_OF_MONTH)).show();}
 private void renderCategories(){categoryBox.removeAllViews();if(categories.isEmpty()){categoryBox.addView(label("Создай свою первую категорию",15,MUTED,false));return;}LinearLayout row=null;for(int i=0;i<categories.size();i++){if(i%2==0){row=new LinearLayout(this);categoryBox.addView(row);}String n=categories.get(i).name;Button b=action((selected.equals(n)?"✓  ":"")+n,()->{selected=n;renderCategories();},selected.equals(n));b.setTextSize(15);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,-2,1);p.setMargins(0,dp(4),dp(6),dp(4));row.addView(b,p);}}
 private void newCategory(){EditText name=input("Название категории",18);name.setSingleLine(true);name.setPadding(dp(24),dp(12),dp(24),dp(12));name.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(40)});AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Новая категория").setView(name).setPositiveButton("Создать",null).setNegativeButton("Отмена",null).create();dialog.setOnShowListener(x->{dialog.getButton(-1).setOnClickListener(v->{String n=name.getText().toString().trim();if(n.isEmpty()){name.setError("Введи название");return;}for(Category c:categories)if(c.name.equalsIgnoreCase(n)){selected=c.name;renderCategories();dialog.dismiss();return;}dialog.getButton(-1).setEnabled(false);change(()->db.ledger().addCategory(new Category(n)),()->{selected=n;renderCategories();dialog.dismiss();});});name.requestFocus();dialog.getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_STATE_ALWAYS_VISIBLE);});dialog.show();}
 private void save(){long cents;try{cents=new BigDecimal(amount.getText().toString().trim().replace(',','.')).movePointRight(2).longValueExact();if(cents<=0||cents>99999999900L)throw new NumberFormatException();}catch(Exception e){amount.setError("Сумма больше нуля, максимум 2 знака после запятой");return;}if(selected.isEmpty()){Toast.makeText(this,"Выбери или создай категорию",Toast.LENGTH_SHORT).show();return;}Expense expense=new Expense();expense.id=editId;expense.cents=cents;expense.category=selected;expense.time=editTime;expense.note=note.getText().toString().trim();boolean close=payment;change(()->db.runInTransaction(()->{if(expense.id==0)db.ledger().addExpense(expense);else if(db.ledger().updateExpense(expense)!=1)throw new IllegalStateException("Missing expense");db.ledger().setting(new Setting("lastCategory",expense.category));}),()->{((InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(amount.getWindowToken(),0);Toast.makeText(this,"Сохранено",Toast.LENGTH_SHORT).show();if(close)finish();else home();});}
 private void confirmDelete(Expense e){new AlertDialog.Builder(this).setTitle("Удалить расход?").setMessage(e.category+" · "+money(e.cents)+" с.\nЗапись исчезнет из истории и итогов.").setNegativeButton("Отмена",null).setPositiveButton("Удалить",(d,w)->change(()->{if(db.ledger().deleteExpense(e.id)!=1)throw new IllegalStateException("Missing expense");},()->home())).show();}
 private void settings(){base("settings");page.addView(label("Настройки",33,INK,true));section("Твои данные");LinearLayout c=card();c.addView(label("Экспорт расходов",20,INK,true));c.addView(label("CSV для Excel и Google Таблиц. Все записи, категории, даты и заметки.",15,MUTED,false));c.addView(action("Экспортировать CSV",()->export(),true));c.addView(label("Записей: "+entries.size()+" · Категорий: "+categories.size(),13,MUTED,false));section("Автоматизация");LinearLayout a=card();a.addView(label("После оплаты в Alif",20,INK,true));a.addView(label("Форма появляется после результата оплаты. Сумма подставляется автоматически; категорию выбираешь ты.",15,MUTED,false));a.addView(action("Открыть специальные возможности",()->startActivity(new Intent(android.provider.Settings.ACTION_ACCESSIBILITY_SETTINGS)),false));section("Хранение");LinearLayout info=card();info.addView(label("На твоём телефоне",20,INK,true));info.addView(label("История хранится локально. Сохрани CSV перед удалением приложения или очисткой данных.",15,MUTED,false));info.addView(label("Room · SQLite  /  версия 1.1.0",12,MUTED,false));}
 private void export(){Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("text/csv").putExtra(Intent.EXTRA_TITLE,"Расходы_"+new SimpleDateFormat("yyyy-MM-dd",Locale.ROOT).format(new Date())+".csv");startActivityForResult(i,70);}
 protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request!=70||result!=RESULT_OK||data==null||data.getData()==null)return;android.net.Uri uri=data.getData();LedgerDatabase.IO.execute(()->{try(OutputStream out=getContentResolver().openOutputStream(uri,"wt")){if(out==null)throw new IOException("No output");CsvExport.write(out,db.ledger().expenses());runOnUiThread(()->Toast.makeText(this,"CSV сохранён",Toast.LENGTH_LONG).show());}catch(Exception e){runOnUiThread(()->error(e));}});}
 @Override public void onBackPressed(){if(!screen.equals("home")&&!payment)home();else super.onBackPressed();}
}
